PRAGMA foreign_keys=ON;
CREATE TABLE members(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE COLLATE NOCASE,display_name TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('admin','member')),status TEXT NOT NULL DEFAULT 'active',notifications_enabled INTEGER NOT NULL DEFAULT 1,created_at_ms INTEGER NOT NULL);
CREATE TABLE devices(id TEXT PRIMARY KEY,member_id TEXT NOT NULL REFERENCES members(id),device_label TEXT NOT NULL,token_hash TEXT NOT NULL UNIQUE,platform TEXT NOT NULL,agent_version TEXT,last_seen_at_ms INTEGER,revoked_at_ms INTEGER,created_at_ms INTEGER NOT NULL);
CREATE INDEX devices_member ON devices(member_id);
CREATE TABLE enrollment_codes(code_hash TEXT PRIMARY KEY,member_id TEXT NOT NULL REFERENCES members(id),expires_at_ms INTEGER NOT NULL,used_at_ms INTEGER,created_at_ms INTEGER NOT NULL);
CREATE TABLE model_prices(id TEXT PRIMARY KEY,model_id TEXT NOT NULL COLLATE NOCASE,input_price INTEGER NOT NULL CHECK(input_price>=0),output_price INTEGER NOT NULL CHECK(output_price>=0),cache_read_price INTEGER NOT NULL CHECK(cache_read_price>=0),cache_write_price INTEGER NOT NULL CHECK(cache_write_price>=0),effective_from INTEGER NOT NULL,catalog_version TEXT NOT NULL,source TEXT NOT NULL,UNIQUE(model_id,catalog_version,effective_from));
CREATE TABLE usage_events(id TEXT NOT NULL,device_id TEXT NOT NULL REFERENCES devices(id),member_id TEXT NOT NULL REFERENCES members(id),session_key TEXT NOT NULL,step_index INTEGER NOT NULL,model_id TEXT NOT NULL,model_display TEXT NOT NULL,source TEXT NOT NULL,occurred_at_ms INTEGER NOT NULL,input_tokens INTEGER NOT NULL,output_tokens INTEGER NOT NULL,cache_read_tokens INTEGER NOT NULL,cache_write_tokens INTEGER NOT NULL,total_tokens INTEGER NOT NULL,pricing_status TEXT NOT NULL CHECK(pricing_status IN ('priced','unpriced')),cost_micro_usd INTEGER,price_id TEXT REFERENCES model_prices(id),updated_at_ms INTEGER NOT NULL,PRIMARY KEY(device_id,id));
ALTER TABLE usage_events ADD COLUMN payload_hash TEXT NOT NULL DEFAULT '';
CREATE INDEX usage_member ON usage_events(member_id);
CREATE INDEX usage_time ON usage_events(occurred_at_ms);
CREATE INDEX usage_model ON usage_events(model_id);
CREATE INDEX usage_member_time ON usage_events(member_id,occurred_at_ms);
CREATE TABLE alert_rules(id TEXT PRIMARY KEY,scope TEXT NOT NULL CHECK(scope IN ('member','family')),member_id TEXT REFERENCES members(id),metric TEXT NOT NULL CHECK(metric IN ('tokens','cost_micro_usd')),period TEXT NOT NULL CHECK(period IN ('day','week','month','rolling_24h')),threshold_value INTEGER NOT NULL CHECK(threshold_value>0),enabled INTEGER NOT NULL DEFAULT 1);
CREATE TABLE alert_notifications(id TEXT PRIMARY KEY,rule_id TEXT NOT NULL REFERENCES alert_rules(id),member_id TEXT,message TEXT NOT NULL,value INTEGER NOT NULL,threshold_value INTEGER NOT NULL,period_start_ms INTEGER NOT NULL,created_at_ms INTEGER NOT NULL,UNIQUE(rule_id,member_id,period_start_ms));
CREATE INDEX alerts_time ON alert_notifications(created_at_ms,id);
CREATE TABLE alert_state(rule_id TEXT NOT NULL,subject_id TEXT NOT NULL,period_start_ms INTEGER NOT NULL,notification_id TEXT NOT NULL,PRIMARY KEY(rule_id,subject_id,period_start_ms));
CREATE TABLE alert_acks(device_id TEXT NOT NULL REFERENCES devices(id),notification_id TEXT NOT NULL REFERENCES alert_notifications(id),acked_at_ms INTEGER NOT NULL,PRIMARY KEY(device_id,notification_id));
CREATE TABLE dashboard_alert_acks(member_id TEXT NOT NULL REFERENCES members(id),notification_id TEXT NOT NULL REFERENCES alert_notifications(id),acked_at_ms INTEGER NOT NULL,PRIMARY KEY(member_id,notification_id));
CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
INSERT INTO settings VALUES('timezone','Asia/Shanghai');
CREATE TABLE enrollment_rate_limits(bucket TEXT PRIMARY KEY,attempts INTEGER NOT NULL,expires_at_ms INTEGER NOT NULL);
